async function loadAfcl(){if(A.data)return A;if(A.loading)return A.loading;A.loading=(async()=>{A.manifest=await json("data/manifest.json");A.data=await json(A.manifest.snapshot);buildSeeding();if(isFinal())A.draw=buildOfficialDraw();return A})().catch(e=>{A.loading=null;throw e});return A.loading}
function buildSeeding(){const q=AFCL.qualificationGw;const rows=(A.data.individual||[]).map(base=>{const hs=(A.data.histories?.[base.id]||[]).map(Number),gw2=Number(hs[q-1]||0),total=hs.slice(0,q).reduce((s,x)=>s+x,0);return {...base,gw2,total,tie:hashString(`${AFCL.tieSeed}|${base.id}`)}}).sort((a,b)=>b.gw2-a.gw2||b.total-a.total||a.tie-b.tie||String(a.team_name||"").localeCompare(String(b.team_name||"")));rows.forEach((r,i)=>{r.seed=i+1;r.qualified=i<AFCL.qualifiers;r.pot=r.qualified?Math.floor(i/AFCL.potSize)+1:null});A.seeding=rows;A.seedMap=new Map(rows.map(r=>[String(r.id),r]))}
function candidateDraw(attempt){const groups=GROUP_LABELS.map(label=>({label,members:[],potCounts:[0,0,0,0,0],chapterCounts:new Map()})),rng=mulberry32(hashString(`${AFCL.drawSeed}|${attempt}`));for(let pot=1;pot<=4;pot++){const teams=A.seeding.filter(x=>x.qualified&&x.pot===pot),freq=new Map();teams.forEach(t=>freq.set(t.chapter,(freq.get(t.chapter)||0)+1));const ordered=shuffled(teams,rng).sort((a,b)=>(freq.get(b.chapter)||0)-(freq.get(a.chapter)||0));for(const team of ordered){let best=null,score=Infinity;for(const g of groups){if(g.potCounts[pot]>=6)continue;const same=g.chapterCounts.get(team.chapter)||0,s=same*100000+g.potCounts[pot]*1000+g.members.length*10+rng();if(s<score){score=s;best=g}}if(!best)throw new Error("AFCL draw capacity error");best.members.push(team);best.potCounts[pot]++;best.chapterCounts.set(team.chapter,(best.chapterCounts.get(team.chapter)||0)+1)}}let collisions=0,maxSame=0;for(const g of groups)for(const c of g.chapterCounts.values()){if(c>1)collisions+=c-1;maxSame=Math.max(maxSame,c)}return{groups,collisions,maxSame,attempt}}
function buildOfficialDraw(){let best=null;for(let a=0;a<120;a++){const c=candidateDraw(a);if(!best||c.collisions<best.collisions||(c.collisions===best.collisions&&c.maxSame<best.maxSame))best=c;if(best.collisions===0)break}const reveal=[];for(let pot=1;pot<=4;pot++){const teams=A.seeding.filter(x=>x.qualified&&x.pot===pot),order=shuffled(teams,mulberry32(hashString(`${AFCL.drawSeed}|REVEAL|P${pot}`))),map=new Map();best.groups.forEach(g=>g.members.filter(x=>x.pot===pot).forEach(x=>map.set(String(x.id),g.label)));order.forEach(t=>reveal.push({...t,group:map.get(String(t.id))}))}const byId=new Map();best.groups.forEach(g=>g.members.forEach(x=>byId.set(String(x.id),g.label)));return{...best,reveal,byId}}
function fixtureRoundsForGroup(group){const teams=[...group.members].sort((a,b)=>a.seed-b.seed),n=teams.length;if(n!==24)return[];const list=[...teams],rounds=[];for(let r=0;r<n-1;r++){const matches=[];for(let i=0;i<n/2;i++){let home=list[i],away=list[n-1-i];if((r+i)%2===1)[home,away]=[away,home];matches.push({home,away})}rounds.push(matches);const fixed=list[0],rest=list.slice(1);rest.unshift(rest.pop());list.splice(0,list.length,fixed,...rest)}return rounds}
function groupStandings(group,throughGw=currentGw()){const rounds=fixtureRoundsForGroup(group),start=AFCL.groupStartGw,end=Math.min(throughGw,AFCL.groupEndGw),stats=new Map(group.members.map(t=>[String(t.id),{...t,p:0,w:0,d:0,l:0,pf:0,pa:0,gd:0,pts:0,h2h:new Map()}]));if(end<start)return[...stats.values()].sort((a,b)=>a.seed-b.seed);for(let gw=start;gw<=end;gw++){const round=rounds[gw-start];if(!round)continue;for(const m of round){const hs=Number((A.data.histories?.[m.home.id]||[])[gw-1]||0),as=Number((A.data.histories?.[m.away.id]||[])[gw-1]||0),h=stats.get(String(m.home.id)),a=stats.get(String(m.away.id));h.p++;a.p++;h.pf+=hs;h.pa+=as;a.pf+=as;a.pa+=hs;if(hs>as){h.w++;a.l++;h.pts+=3;h.h2h.set(String(a.id),3);a.h2h.set(String(h.id),0)}else if(hs<as){a.w++;h.l++;a.pts+=3;a.h2h.set(String(h.id),3);h.h2h.set(String(a.id),0)}else{h.d++;a.d++;h.pts++;a.pts++;h.h2h.set(String(a.id),1);a.h2h.set(String(h.id),1)}}}const rows=[...stats.values()];rows.forEach(x=>x.gd=x.pf-x.pa);const byPts=new Map();rows.forEach(x=>{if(!byPts.has(x.pts))byPts.set(x.pts,[]);byPts.get(x.pts).push(x)});const out=[];[...byPts.keys()].sort((a,b)=>b-a).forEach(pts=>{const tied=byPts.get(pts);tied.forEach(x=>x.mini=tied.reduce((s,y)=>s+(x.id===y.id?0:(x.h2h.get(String(y.id))||0)),0));tied.sort((a,b)=>b.mini-a.mini||b.pf-a.pf||b.gd-a.gd||a.seed-b.seed);out.push(...tied)});out.forEach((x,i)=>x.pos=i+1);return out}

function tabs(active){return `<nav class="afcl-tabs" aria-label="AFCL sections">${[["overview","Overview"],["qualification","Qualification"],["pots","Pots"],["draw","Live Draw"],["groups","Groups"],["knockout","Knockout"],["rules","Rules & FAQ"]].map(([r,l])=>`<a href="${ah(r)}" class="${active===r?"active":""}">${l}</a>`).join("")}</nav>`}
function pageHead(title,sub){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(sub||"")}</p></div></div>`}
function notice(){return isFinal()?'<div class="afcl-alert final"><strong>GW2 scores are FINAL.</strong> AFCL qualification and seeding are locked using the official GW2 data.</div>':'<div class="afcl-alert"><strong>PROVISIONAL AFCL STANDINGS</strong> Qualification, seed and pot can change until FPL finalises GW2.</div>'}
function hero(){return `<section class="hero"><div class="afcl-hero-grid"><div><div class="eyebrow">ANSARA FPL • ${AFCL.season}</div><h1>ANSARA Fantasy Champions League</h1><p>Head-to-Head competition from GW2 qualification through the Group Stage and a knockout road to the GW38 Grand Final.</p><div class="hero-meta"><span>803 Managers</span><span>768 Qualifiers</span><span>32 Groups</span><span>128 Knockout Teams</span></div></div><img class="afcl-logo" src="${AFCL_LOGO_DATA}" alt="ANSARA Fantasy Champions League 2026/27"></div></section>`}
function seedTable(rows,cut=true){return `<div class="afcl-table-wrap"><table class="afcl-table"><thead><tr><th>Seed</th><th>Team / Manager</th><th>Chapter</th><th>GW2</th><th>Overall</th><th>Pot</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr class="${cut&&r.seed===769?"afcl-cut":""}"><td class="afcl-rank">#${r.seed}</td><td><a class="afcl-team" href="${ah(`manager/${enc(r.id)}`)}">${esc(r.team_name)}</a><span class="afcl-sub">${esc(r.manager_name)}</span></td><td>${esc(r.chapter)}</td><td><strong>${nfmt(r.gw2)}</strong></td><td>${nfmt(r.total)}</td><td>${r.pot?`<span class="afcl-badge p${r.pot}">POT ${r.pot}</span>`:"—"}</td><td><span class="afcl-badge ${r.qualified?"q":"out"}">${r.qualified?"QUALIFIED":"OUT"}</span></td></tr>`).join("")}</tbody></table></div>`}
function overviewPage(){const q=A.seeding.filter(x=>x.qualified),cut=q.at(-1),leader=A.seeding[0];return `${hero()}${notice()}<div class="afcl-kpis"><div class="afcl-kpi"><span>#1 Seed</span><strong>${nfmt(leader?.gw2)}</strong><small>${esc(leader?.team_name||"—")}</small></div><div class="afcl-kpi"><span>Qualification Cut</span><strong>#768</strong><small>${cut?`${nfmt(cut.gw2)} pts • ${esc(cut.team_name)}`:"—"}</small></div><div class="afcl-kpi"><span>Qualifiers</span><strong>768</strong><small>Bottom 35 eliminated</small></div><div class="afcl-kpi"><span>Group Stage</span><strong>GW3</strong><small>23 H2H rounds</small></div></div><section class="afcl-card"><div class="afcl-card-head"><div><h2>Competition Timeline</h2><p>GW2 to GW38</p></div><a class="afcl-btn light" href="${ah("rules")}">Rules & FAQ</a></div><div class="afcl-timeline"><div class="afcl-timeline-item"><b>GW2</b><div><strong>Qualification & Seeding</strong><small>Top 768 qualify.</small></div></div><div class="afcl-timeline-item"><b>After GW2</b><div><strong>Official Live Draw</strong><small>4 pots, 32 groups, chapter protection prioritised.</small></div></div><div class="afcl-timeline-item"><b>GW3–25</b><div><strong>Group Stage</strong><small>23 H2H matches. Top 4 advance.</small></div></div><div class="afcl-timeline-item"><b>GW26–37</b><div><strong>Knockout Stage</strong><small>R128 to Semi Final over two legs.</small></div></div><div class="afcl-timeline-item"><b>GW38</b><div><strong>Grand Final</strong><small>One Gameweek. One champion.</small></div></div></div></section><section class="afcl-card"><div class="afcl-card-head"><div><h2>Official Top Seeds</h2><p>GW2 seeding is locked</p></div><a class="afcl-btn light" href="${ah("qualification")}">View all 803</a></div>${seedTable(A.seeding.slice(0,12),false)}</section>`}
function qualificationPage(){const q=A.search.trim().toLowerCase();let rows=A.seeding;if(A.filter==="Q")rows=rows.filter(x=>x.qualified);if(A.filter==="OUT")rows=rows.filter(x=>!x.qualified);if(q)rows=rows.filter(x=>`${x.team_name} ${x.manager_name} ${x.chapter}`.toLowerCase().includes(q));return `${pageHead("Qualification & Seeding","Official GW2 ranking • Top 768 qualify")}${notice()}<div class="afcl-search"><input id="afclQualSearch" value="${esc(A.search)}" placeholder="Search team, manager or chapter"><select id="afclQualFilter"><option value="ALL">All 803</option><option value="Q" ${A.filter==="Q"?"selected":""}>Qualified</option><option value="OUT" ${A.filter==="OUT"?"selected":""}>Eliminated</option></select></div><section class="afcl-card">${seedTable(rows,true)}</section>`}
function potsPage(){return `${pageHead("Seeding Pots","Official • 4 pots × 192 teams")}${notice()}<div class="pot-grid">${[1,2,3,4].map(p=>{const rows=A.seeding.filter(x=>x.pot===p);return `<article class="pot-card"><div class="pot-head"><strong>POT ${p}</strong><span>Seeds ${rows[0]?.seed}–${rows.at(-1)?.seed}</span></div><div class="pot-list">${rows.map(r=>`<div class="pot-row"><div class="seed">#${r.seed}</div><div><strong>${esc(r.team_name)}</strong><small>${esc(r.manager_name)} • ${esc(r.chapter)}</small></div><div>${nfmt(r.gw2)}</div></div>`).join("")}</div></article>`}).join("")}</div>`}

async function hostDigest(v){const b=new TextEncoder().encode(v),h=await crypto.subtle.digest("SHA-256",b);return[...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function unlockHost(){if(!A.hostMode)return;const code=prompt("Enter AFCL host code");if(!code)return;if(await hostDigest(code.trim())===AFCL_HOST_HASH){A.hostAuthorized=true;sessionStorage.setItem("afcl-host-ok","1");renderAfcl(["draw"])}else alert("Invalid AFCL host code.")}
async function writeLive(patch){if(!A.hostAuthorized)throw new Error("Host control unavailable");const next={...A.live,...patch,updated_at:new Date().toISOString()};A.live=next;await update(afclLiveRef,next)}
function drawPage(){if(!isFinal())return `${pageHead("AFCL Live Draw","Official draw unlocks after GW2 is FINAL")}${notice()}`;const status=A.live.status||"pending";if(A.hostMode&&!A.hostAuthorized)return `${pageHead("AFCL Live Draw","Host control")}<div class="afcl-alert final"><strong>GW2 qualification is locked.</strong> Unlock the host console to start the official draw. Public visitors do not get draw controls.</div><section class="draw-stage"><div class="draw-reveal"><div><div class="pot">HOST CONTROL</div><h2>Official draw ready</h2><p>768 teams • 32 groups • deterministic allocation</p><button id="afclHostUnlock" class="afcl-primary" type="button">Unlock Host Console</button></div></div></section>`;if(status==="pending"&&!A.hostAuthorized)return `${pageHead("AFCL Live Draw","Qualification final • official draw pending")}<div class="afcl-alert final"><strong>Qualification and seeding are official.</strong> The draw begins only when the AFCL host triggers it.</div><section class="draw-stage"><div class="draw-reveal"><div><div class="pot">OFFICIAL LIVE DRAW</div><h2>Waiting for host</h2><p>32 groups • 24 teams each • same-chapter separation prioritised</p></div></div></section>`;return liveDrawStage()}
function liveDrawStage(){const total=A.draw.reveal.length,idx=Math.min(Number(A.live.index||0),total),pct=(idx/total*100).toFixed(1),current=idx?A.draw.reveal[idx-1]:null,next=A.draw.reveal[idx]||null,done=idx>=total||A.live.status==="complete",running=A.live.status==="running",paused=A.live.status==="paused";const reveal=current?`<div><div class="pot">POT ${current.pot} • SEED #${current.seed}</div><h2>${esc(current.team_name)}</h2><p>${esc(current.manager_name)}</p><p>${esc(current.chapter)}</p><div class="destination">GROUP <b>${esc(current.group)}</b></div></div>`:`<div><div class="pot">AFCL OFFICIAL DRAW</div><h2>768 teams. 32 groups.</h2><p>${A.hostAuthorized?"Press Start once. The draw reveals every team automatically.":"Waiting for the first reveal."}</p></div>`;const controls=A.hostAuthorized?`<div class="draw-controls"><button id="afclDrawStart" ${done||running?"disabled":""}>${idx?"Resume Draw":"Start Live Draw"}</button><button id="afclDrawPause" class="secondary" ${!running||done?"disabled":""}>Pause</button><select id="afclDrawSpeed"><option value="1" ${A.drawSpeed===1?"selected":""}>1× • 3 sec</option><option value="1.5" ${A.drawSpeed===1.5?"selected":""}>1.5×</option><option value="2" ${A.drawSpeed===2?"selected":""}>2×</option></select></div>`:"";return `${pageHead("AFCL Live Draw",done?"Official draw complete":paused?"Official draw paused":running?"LIVE • synced for all viewers":"Official draw console")}<section class="draw-stage"><div class="draw-progress"><strong>${done?"DRAW COMPLETE":`Draw ${idx} / ${total}`}</strong><span>${done?"All groups complete":next?`Next: Pot ${next.pot}`:"Ready"}</span></div><div class="draw-bar"><i style="width:${pct}%"></i></div><div class="draw-reveal">${reveal}</div>${controls}<div class="draw-note">${A.hostAuthorized?"Host controls update the shared live position.":"Live progress is controlled by the AFCL host."} Refresh returns to the current official position.</div></section>${drawBoard(idx)}`}
function drawBoard(idx){const shown=new Map(GROUP_LABELS.map(g=>[g,[]]));A.draw.reveal.slice(0,idx).forEach(x=>shown.get(x.group).push(x));return `<section class="afcl-card"><div class="afcl-card-head"><div><h2>Live Group Board</h2><p>${idx} of 768 teams revealed</p></div></div><div class="afcl-group-grid" style="padding:0 12px 12px">${GROUP_LABELS.map(g=>`<article class="afcl-group-card"><div class="afcl-group-head"><strong>GROUP ${g}</strong><span>${shown.get(g).length}/24</span></div><div class="afcl-group-list">${shown.get(g).slice(-6).map((r,i)=>`<div class="afcl-group-row"><div class="slot">${Math.max(1,shown.get(g).length-5+i)}</div><div><strong>${esc(r.team_name)}</strong><small>${esc(r.manager_name)} • ${esc(r.chapter)}</small></div><div>P${r.pot}</div></div>`).join("")||'<div class="afcl-empty">Awaiting draw</div>'}</div></article>`).join("")}</div></section>`}
function bindDraw(){document.getElementById("afclHostUnlock")?.addEventListener("click",unlockHost);document.getElementById("afclDrawStart")?.addEventListener("click",async()=>{if(!A.hostAuthorized)return;A.drawPaused=false;A.drawRunning=true;A.drawIndex=Number(A.live.index||0);await writeLive({status:"running",index:A.drawIndex,speed:A.drawSpeed});runDraw()});document.getElementById("afclDrawPause")?.addEventListener("click",async()=>{if(!A.hostAuthorized)return;A.drawPaused=true;A.drawRunning=false;clearTimeout(A.drawTimer);await writeLive({status:"paused",index:A.drawIndex,speed:A.drawSpeed});renderAfcl(["draw"])});document.getElementById("afclDrawSpeed")?.addEventListener("change",async e=>{A.drawSpeed=Number(e.target.value)||1;if(A.hostAuthorized)await writeLive({speed:A.drawSpeed,index:Number(A.live.index||0),status:A.live.status||"pending"})})}
async function runDraw(){clearTimeout(A.drawTimer);if(!A.drawRunning||A.drawPaused||!A.hostAuthorized)return;const total=A.draw.reveal.length;if(A.drawIndex>=total){A.drawRunning=false;await writeLive({status:"complete",index:total,speed:A.drawSpeed,completed_at:new Date().toISOString()});renderAfcl(["draw"]);return}A.drawIndex++;await writeLive({status:A.drawIndex>=total?"complete":"running",index:A.drawIndex,speed:A.drawSpeed});renderAfcl(["draw"]);if(A.drawIndex>=total){A.drawRunning=false;return}const checkpoint=A.drawIndex%192===0&&A.drawIndex<total,delay=(checkpoint?9000:3000)/A.drawSpeed;A.drawTimer=setTimeout(runDraw,delay)}
function groupSelector(){return `<div class="group-select">${GROUP_LABELS.map(g=>`<button data-afcl-group="${g}" class="${A.selectedGroup===g?"active":""}">${g}</button>`).join("")}</div>`}
function standingTable(rows,started){return `<div class="afcl-table-wrap"><table class="afcl-table"><thead><tr><th>#</th><th>Team / Manager</th><th>Chapter</th>${started?"<th>P</th><th>W</th><th>D</th><th>L</th><th>PF</th><th>PA</th><th>GD</th><th>PTS</th>":"<th>Seed</th><th>Pot</th>"}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${started&&i<4?"standing-qualify":""}"><td class="afcl-rank">${started?`#${r.pos}`:i+1}</td><td><a class="afcl-team" href="${ah(`manager/${enc(r.id)}`)}">${esc(r.team_name)}</a><span class="afcl-sub">${esc(r.manager_name)}</span></td><td>${esc(r.chapter)}</td>${started?`<td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.pf}</td><td>${r.pa}</td><td>${r.gd}</td><td><strong>${r.pts}</strong></td>`:`<td>#${r.seed}</td><td>P${r.pot}</td>`}</tr>`).join("")}</tbody></table></div>`}
function fixtures(g){const rounds=fixtureRoundsForGroup(g),current=currentGw();return `<section class="afcl-card"><div class="afcl-card-head"><div><h2>Group ${g.label} Fixtures</h2><p>GW3–GW25 • 23 rounds</p></div></div>${rounds.map((matches,i)=>{const gw=AFCL.groupStartGw+i;return `<div class="fixture-round"><h4>GAMEWEEK ${gw}</h4>${matches.map(m=>{const played=current>=gw,hs=played?Number((A.data.histories?.[m.home.id]||[])[gw-1]||0):null,as=played?Number((A.data.histories?.[m.away.id]||[])[gw-1]||0):null;return `<div class="fixture"><div class="home"><strong>${esc(m.home.team_name)}</strong><small>${esc(m.home.manager_name)} • ${esc(m.home.chapter)}</small></div><div class="score">${played?`${hs}–${as}`:"vs"}</div><div class="away"><strong>${esc(m.away.team_name)}</strong><small>${esc(m.away.manager_name)} • ${esc(m.away.chapter)}</small></div></div>`}).join("")}</div>`}).join("")}</section>`}
function groupsPage(){if(!drawComplete())return `${pageHead("AFCL Groups","Awaiting Official Live Draw")}<div class="afcl-alert final"><strong>The 768 qualifiers are locked.</strong> Groups appear here when the host completes the official Live Draw.</div>`;const g=A.draw.groups.find(x=>x.label===A.selectedGroup)||A.draw.groups[0],started=currentGw()>=AFCL.groupStartGw,rows=groupStandings(g);return `${pageHead("AFCL Group Stage","32 groups • 24 teams • Top 4 qualify")}${groupSelector()}<section class="afcl-card"><div class="afcl-card-head"><div><h2>Group ${g.label}</h2><p>${started?`Standings through GW${Math.min(currentGw(),25)}`:"Official draw roster • Group Stage starts GW3"}</p></div></div>${standingTable(rows,started)}</section>${fixtures(g)}`}
function knockoutPage(){return `${pageHead("AFCL Knockout","128 teams • starts GW26")}<section class="afcl-card"><div class="afcl-timeline"><div class="afcl-timeline-item"><b>GW26–27</b><div><strong>Round of 128</strong><small>Two legs. No same-group matchup; same-chapter protection prioritised.</small></div></div><div class="afcl-timeline-item"><b>GW28–29</b><div><strong>Round of 64</strong><small>Two legs.</small></div></div><div class="afcl-timeline-item"><b>GW30–31</b><div><strong>Round of 32</strong><small>Two legs.</small></div></div><div class="afcl-timeline-item"><b>GW32–33</b><div><strong>Round of 16</strong><small>Two legs.</small></div></div><div class="afcl-timeline-item"><b>GW34–35</b><div><strong>Quarter Final</strong><small>Two legs.</small></div></div><div class="afcl-timeline-item"><b>GW36–37</b><div><strong>Semi Final</strong><small>Two legs.</small></div></div><div class="afcl-timeline-item"><b>GW38</b><div><strong>Grand Final</strong><small>One Gameweek.</small></div></div></div></section><div class="afcl-alert"><strong>Knockout bracket is not active yet.</strong> Top 4 from each group qualify after GW25.</div>`}
function rulesPage(){return `${pageHead("Rules & FAQ","ANSARA FPL 2026/27 • Competition Guide v1.0")}<section class="afcl-card rules-section"><h2>ANSARA FPL Competition Guide</h2><h3>Individual Classic</h3><ul><li>Runs GW1–GW38.</li><li>Managers compete on cumulative official FPL points.</li><li>Transfer hits are included in the net Gameweek score.</li><li>Highest cumulative score after GW38 wins.</li></ul><h3>Chapter / Group Competition</h3><ul><li>Only eligible ANSARA chapters compete.</li><li>Each Gameweek, the Top 5 net scores from each chapter count.</li><li>The Top 5 can change every Gameweek.</li><li>Weekly Top 5 totals accumulate through the season.</li></ul><h3>ANSARA Fantasy Champions League</h3><ul><li>GW2 is Qualification & Seeding.</li><li>Top 768 of 803 qualify.</li><li>Group Stage GW3–GW25; Top 4 per group advance.</li><li>Grand Final is GW38.</li></ul></section><section class="afcl-card rules-section"><h2>AFCL Full Rules</h2><h3>Qualification & Seeding</h3><p>Ranked by Net GW2 Points. Top 768 qualify; bottom 35 are eliminated. Tie-break: GW2 Points → Overall Points after GW2 → digital random draw.</p><h3>Seeding Pots</h3><p>Pot 1: Seeds 1–192. Pot 2: 193–384. Pot 3: 385–576. Pot 4: 577–768.</p><h3>Live Draw</h3><p>32 groups A–AF, 24 teams per group and six from each pot. The algorithm minimises same-chapter teams in the same group as far as mathematically possible. Fixtures are released only after the full draw.</p><h3>Group Stage</h3><p>GW3–GW25. Win 3, Draw 1, Loss 0. Match score uses Net FPL Gameweek Points after transfer hits.</p><h3>Group Tie-break</h3><ol><li>AFCL Points</li><li>Head-to-Head / mini-table</li><li>Points For</li><li>Score Difference</li><li>GW2 Seed</li></ol><h3>Knockout</h3><p>R128 GW26–27, R64 GW28–29, R32 GW30–31, R16 GW32–33, QF GW34–35, SF GW36–37, Grand Final GW38. R128 cannot pair teams from the same group and same-chapter pairings are avoided as far as possible.</p><h3>Aggregate Tie-break</h3><ol><li>Second Leg Score</li><li>Group Stage Finish</li><li>GW2 Seed</li></ol></section><section class="afcl-card rules-section faq"><h2>Quick FAQ</h2><details><summary>Are transfer hits counted?</summary><p>Yes. AFCL uses net Gameweek points after transfer deductions.</p></details><details><summary>Can Seed #769 enter?</summary><p>No. Only the official Top 768 after GW2 qualify.</p></details><details><summary>Why might two managers from one chapter share a group?</summary><p>Only where separation is mathematically unavoidable; duplicates are minimised and distributed.</p></details><details><summary>When are fixtures released?</summary><p>After the complete official Live Draw.</p></details></section>`}
function managerPage(id){const r=A.seedMap.get(String(id));if(!r)return '<div class="empty">Manager not found.</div>';const gl=drawComplete()?A.draw.byId.get(String(r.id)):null,g=gl?A.draw.groups.find(x=>x.label===gl):null,record=g?groupStandings(g).find(x=>String(x.id)===String(r.id)):null;return `${pageHead(r.team_name,`${r.manager_name} • ${r.chapter}`)}<section class="afcl-card"><div class="afcl-card-head"><div><h2>AFCL 2026/27</h2><p>Official competition record</p></div><span class="afcl-badge ${r.qualified?"q":"out"}">${r.qualified?"QUALIFIED":"DID NOT QUALIFY"}</span></div><div class="afcl-kpis" style="padding:0 13px 13px"><div class="afcl-kpi"><span>GW2 Seed</span><strong>#${r.seed}</strong><small>${nfmt(r.gw2)} pts</small></div><div class="afcl-kpi"><span>Pot</span><strong>${r.pot?`P${r.pot}`:"—"}</strong><small>${r.qualified?"Top 768":"Eliminated"}</small></div><div class="afcl-kpi"><span>Group</span><strong>${gl||"—"}</strong><small>${gl?"Official draw":"Not published"}</small></div><div class="afcl-kpi"><span>AFCL Pts</span><strong>${record?.pts??"—"}</strong><small>${record?`P${record.p} W${record.w} D${record.d} L${record.l}`:"Group Stage not active"}</small></div></div></section>${g?`<section class="afcl-card"><div class="afcl-card-head"><div><h2>Group ${g.label}</h2><p>Current AFCL standing</p></div><a class="afcl-btn light" href="${ah("groups")}">View group</a></div>${standingTable(groupStandings(g),currentGw()>=3)}</section>`:""}<a class="afcl-btn light" href="#/manager/${enc(r.id)}">Back to full ANSARA FPL profile</a>`}

function bindAfclEvents(){document.getElementById("afclQualSearch")?.addEventListener("input",e=>{A.search=e.target.value;renderAfcl(["qualification"],false)});document.getElementById("afclQualFilter")?.addEventListener("change",e=>{A.filter=e.target.value;renderAfcl(["qualification"],false)});document.querySelectorAll("[data-afcl-group]").forEach(b=>b.addEventListener("click",()=>{A.selectedGroup=b.dataset.afclGroup;renderAfcl(["groups"])}));bindDraw()}
async function renderAfcl(route=afclRoute(),scroll=true){if(!route)return;const appEl=document.getElementById("app");if(!appEl||A.rendering)return;A.rendering=true;try{ensureAfclNav();await loadAfcl();const p=route[0]||"overview";let body;if(p==="overview")body=overviewPage();else if(p==="qualification")body=qualificationPage();else if(p==="pots")body=potsPage();else if(p==="draw")body=drawPage();else if(p==="groups")body=groupsPage();else if(p==="knockout")body=knockoutPage();else if(p==="rules")body=rulesPage();else if(p==="manager")body=managerPage(decodeURIComponent(route[1]||""));else body=overviewPage();appEl.innerHTML=`${tabs(p)}${body}`;bindAfclEvents();if(scroll)window.scrollTo(0,0)}catch(e){console.error(e);appEl.innerHTML='<div class="empty">Unable to load AFCL. Please refresh.</div>'}finally{A.rendering=false}}
async function enhanceMainRoutes(){ensureAfclNav();const r=(location.hash||"").replace(/^#\/?/,"").split("/").filter(Boolean),route=r[0]||"home",appEl=document.getElementById("app");if(!appEl)return;if(route==="manager"){await loadAfcl().catch(()=>null);const m=A.seedMap.get(String(decodeURIComponent(r[1]||"")));if(!m||document.getElementById("afclManagerCard"))return;const gl=drawComplete()?A.draw?.byId?.get(String(m.id)):null,g=gl?A.draw.groups.find(x=>x.label===gl):null,rec=g?groupStandings(g).find(x=>String(x.id)===String(m.id)):null;const s=document.createElement("section");s.id="afclManagerCard";s.className="section";s.innerHTML=`<div class="section-head"><div><h2>ANSARA Fantasy Champions League</h2><span class="subline">Official GW2 qualification & seeding</span></div></div><div class="profile-kpis" style="padding:0 14px 14px"><div><span>AFCL Status</span><strong style="font-size:14px;color:${m.qualified?"#15803d":"#b91c1c"}">${m.qualified?"Qualified":"Did Not Qualify"}</strong></div><div><span>GW2 Seed</span><strong>#${m.seed}</strong></div><div><span>Pot / Group</span><strong>${m.pot?`P${m.pot}`:"—"}${gl?` • ${gl}`:""}</strong></div><div><span>AFCL Pts</span><strong>${rec?.pts??"—"}</strong></div></div>`;appEl.appendChild(s)}if(route==="more"&&!document.getElementById("afclRulesMoreCard")){const grid=appEl.querySelector(".more-grid");if(grid){const a=document.createElement("a");a.id="afclRulesMoreCard";a.href=ah("rules");a.className="more-card";a.innerHTML="<span>📘</span>Rules & FAQ";grid.appendChild(a)}}}
function routeSync(){const r=afclRoute();if(r)renderAfcl(r);else enhanceMainRoutes()}
const observer=new MutationObserver(()=>{if(!A.rendering)setTimeout(routeSync,0)});const appEl=document.getElementById("app");if(appEl)observer.observe(appEl,{childList:true,subtree:true});window.addEventListener("hashchange",()=>setTimeout(routeSync,0));ensureAfclNav();routeSync();

onValue(afclLiveRef,s=>{A.live={status:"pending",index:0,speed:1,...(s.val()||{})};A.drawIndex=Number(A.live.index||0);A.drawSpeed=Number(A.live.speed||1);A.liveReady=true;if(afclRoute())renderAfcl(afclRoute(),false);else enhanceMainRoutes()},e=>{A.liveReady=true;console.warn("AFCL live sync",e)});
onAuthStateChanged(auth,user=>{if(user)startRealtimeAudience(user)});
signInAnonymously(auth).catch(e=>{console.error("Anonymous sign-in failed",e);audienceUnavailable()});
